import re
import pytest
from hypothesis import given, example
import hypothesis.strategies as st

from roman import to_roman, from_roman


# ---- obviously-correct reference model for to_roman ----
_REF_TABLE = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

def _ref_to_roman(n: int) -> str:
    out = []
    r = n
    for v, sym in _REF_TABLE:
        while r >= v:
            out.append(sym)
            r -= v
    return "".join(out)


_CANONICAL_RE = re.compile(r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$")

def _is_canonical_form(s: str) -> bool:
    if s == "":
        return False
    m = _CANONICAL_RE.match(s)
    return m is not None and m.group(0) == s and s != "" and not (
        s == "" or _CANONICAL_RE.match(s) is None
    ) and s != ""


# ---- examples from spec ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_58():
    assert from_roman("LVIII") == 58

def test_example_from_roman_IIII_raises():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_raises():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- to_roman range / type ----
def test_to_roman_boundaries():
    assert to_roman(1) == "I"
    assert to_roman(3999) == "MMMCMXCIX"

def test_to_roman_out_of_range():
    for bad in [0, -1, -100, 4000, 4001, 10000, -3999]:
        with pytest.raises(ValueError):
            to_roman(bad)

def test_to_roman_type_errors():
    for bad in [True, False, 1.0, 4.0, "IV", "1", None, [4], (4,), 4.5]:
        with pytest.raises(TypeError):
            to_roman(bad)


# ---- from_roman type / basic invalid ----
def test_from_roman_type_errors():
    for bad in [None, 1, 58, 4.0, True, False, b"IV", ["X"], ("X",), 123]:
        with pytest.raises(TypeError):
            from_roman(bad)

def test_from_roman_empty_raises():
    with pytest.raises(ValueError):
        from_roman("")

def test_from_roman_lowercase_raises():
    for s in ["iv", "mcmxciv", "Iv", "iV", "lviii"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_whitespace_raises():
    for s in [" X", "X ", "X\n", "\tX", "X\n", "M CM", "M\tM", "\n", " "]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_unknown_chars_raises():
    for s in ["A", "IIIIA", "N", "ivX", "123", "X!", "M-M", "MMMM", "MMMMM"]:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_noncanonical_raises():
    bad = ["IIII", "VV", "IC", "XM", "IXI", "MMMM", "IIIII",
           "XXXX", "CCCC", "LL", "DD", "VL", "IL", "XD", "IM",
           "IXIX", "IVIV", "CMCM", "IXI", "VIV", "IIV", "IIX",
           "MIM", "DCD", "LXL", "VIX", "XIL"]
    for s in bad:
        with pytest.raises(ValueError):
            from_roman(s)


# ---- defect-targeting: duplicated canonical numeral ----
def test_from_roman_duplicated_long_numeral_rejected():
    # "MDCCCLXXXVIII" is canonical for 1888 (length 13 >= 10).
    p = "MDCCCLXXXVIII"
    assert to_roman(1888) == p  # sanity vs spec example style
    doubled = p + p
    # 2*1888 = 3776 is in range, but doubled string is not canonical,
    # so spec requires ValueError.
    with pytest.raises(ValueError):
        from_roman(doubled)

def test_from_roman_duplicated_medium_numeral_rejected():
    p = "MDCCLXXXVIII"  # 1788, length 12
    assert to_roman(1788) == p
    with pytest.raises(ValueError):
        from_roman(p + p)

def test_from_roman_any_doubled_canonical_rejected():
    # Any s+s (non-empty) is never canonical for 1..3999 range
    # except it must raise. Check a few long ones.
    for n in [1788, 1888, 1777, 2888 - 1000]:
        p = _ref_to_roman(n)
        if len(p) >= 10:
            with pytest.raises(ValueError):
                from_roman(p + p)


# ---- invariants / properties ----
@given(st.integers(min_value=1, max_value=3999))
def test_property_roundtrip_to_from(n):
    assert from_roman(to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_property_to_roman_matches_reference(n):
    assert to_roman(n) == _ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_property_to_roman_canonical_shape(n):
    s = to_roman(n)
    assert isinstance(s, str)
    assert s == s.upper()
    assert _CANONICAL_RE.match(s) is not None
    # only allowed subtractive pairs; check no forbidden pairs appear
    for bad_pair in ["IL", "IC", "ID", "IM", "XD", "XM", "VX", "VL", "VC", "VD", "VM", "LC", "LD", "LM", "DM"]:
        assert bad_pair not in s
    # never four in a row of I, X, C; never doubled V, L, D
    assert "IIII" not in s and "XXXX" not in s and "CCCC" not in s and "MMMM" not in s
    assert "VV" not in s and "LL" not in s and "DD" not in s

@given(st.integers(min_value=1, max_value=3999))
def test_property_from_roman_result_in_range(n):
    v = from_roman(to_roman(n))
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999

@given(st.integers(min_value=1, max_value=3999))
def test_property_to_from_to_idempotent(n):
    assert to_roman(from_roman(to_roman(n))) == to_roman(n)

@given(st.text(alphabet="IVXLCDM", min_size=0, max_size=12))
def test_property_from_roman_accepted_implies_canonical(s):
    try:
        v = from_roman(s)
    except ValueError:
        return
    # accepted => must satisfy strict inverse invariants
    assert isinstance(v, int) and not isinstance(v, bool)
    assert 1 <= v <= 3999
    assert to_roman(v) == s

@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=30))
def test_property_from_roman_double_check_with_reference(s):
    # Cross-check: accepted strings must equal reference rendering of value;
    # rejected strings must not equal it.
    try:
        v = from_roman(s)
    except ValueError:
        # if rejected, s must not be canonical rendering of any n
        # verify by brute force over value derived naively is overkill;
        # at least verify s is not reference rendering of some n in range
        # via regex shape (necessary condition)
        assert not (_CANONICAL_RE.match(s) is not None and s != "" and _ref_to_roman(_naive_value(s)) == s if _naive_ok(s) else True) or True
        # stronger: if it looks canonical it must still fail only if out of range;
        # canonical regex strings with value 1..3999 must be accepted, so
        # if s matches regex and naive value in range, then rejection is a bug
        if _CANONICAL_RE.match(s) is not None:
            try:
                nv = _naive_value(s)
            except Exception:
                return
            if 1 <= nv <= 3999 and _ref_to_roman(nv) == s:
                pytest.fail(f"from_roman wrongly rejected canonical {s!r}")
        return
    assert _ref_to_roman(v) == s
    assert to_roman(v) == s

def _naive_value(s: str) -> int:
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        cur = vals[ch]
        if cur < prev:
            total -= cur
        else:
            total += cur
        prev = max(prev, cur) if cur >= prev else prev
        if cur >= prev:
            prev = cur
    return total

def _naive_ok(s: str) -> bool:
    return all(c in "IVXLCDM" for c in s) and len(s) > 0

@given(st.integers(min_value=-5000, max_value=5000))
def test_property_to_roman_valid_iff_in_range(n):
    if isinstance(n, bool):
        with pytest.raises(TypeError):
            to_roman(n)
        return
    if 1 <= n <= 3999:
        assert to_roman(n) == _ref_to_roman(n)
    else:
        with pytest.raises(ValueError):
            to_roman(n)
